/**
 * The OPFS import-once gate (story 392 extracted it from `db.worker.ts`).
 *
 * Adopt ONLY when the on-disk DB is already at (or past) the incoming
 * snapshot's generation. Gating on "any baseline > 0" broke every refresh over
 * an existing snapshot (2026-07-02 prod incident: the stale generation-15 DB
 * was adopted forever while the server sat at 22, looping downloads until two
 * windows wedged the OPFS handles). With no expected generation (legacy
 * callers), any real baseline wins. Either way, never a file without one —
 * an empty-schema fallback (story 215's heal) or, against a generation-0
 * server, a DB with no tables at all (story 360, explore-01).
 */
export function shouldAdoptExisting(onDiskGeneration: number, expectedGeneration: number | null): boolean {
    return onDiskGeneration > 0 && (expectedGeneration === null || onDiskGeneration >= expectedGeneration);
}
