import { TRACKED_TABLES, type TrackedTable } from '@motivation/shared';

function buildJsonObjectSql(alias: 'NEW' | 'OLD', columns: string[]): string {
    return `json_object(${columns.flatMap((column) => [`'${column}'`, `${alias}.${column}`]).join(', ')})`;
}

/**
 * Story 358 — an UPDATE queues the row id and the columns that changed. The whole NEW row would
 * carry every column the replica holds, stale ones included (online writes don't refresh it), and
 * the server's UPSERT would revert whatever it took online since. Unchanged columns are removed
 * from the full object; a changed one points `json_remove` at a key that never exists.
 */
function buildChangedColumnsJsonSql(table: TrackedTable): string {
    const removals = table.columns
        .filter((column) => column !== table.rowIdColumn)
        .map((column) => `CASE WHEN OLD.${column} IS NEW.${column} THEN '$.${column}' ELSE '$.__changed' END`);
    return `json_remove(${buildJsonObjectSql('NEW', table.columns)}, ${removals.join(', ')})`;
}

type TriggerDefinition = { name: string; sql: string };

function insertOrUpdateTrigger(table: TrackedTable, operation: 'INSERT' | 'UPDATE'): TriggerDefinition {
    const name = `_pending_changes_${table.tableName.toLowerCase()}_${operation.toLowerCase()}`;
    const rowData = operation === 'UPDATE' ? buildChangedColumnsJsonSql(table) : buildJsonObjectSql('NEW', table.columns);
    return {
        name,
        sql: [
            `CREATE TRIGGER ${name}`,
            `AFTER ${operation} ON ${table.tableName}`,
            'BEGIN',
            `    INSERT INTO _pending_changes (table_name, row_id, operation, row_data) VALUES ('${table.tableName}', NEW.${table.rowIdColumn}, '${operation}', ${rowData});`,
            'END',
        ].join('\n'),
    };
}

function deleteTrigger(table: TrackedTable): TriggerDefinition {
    const name = `_pending_changes_${table.tableName.toLowerCase()}_delete`;
    return {
        name,
        sql: [
            `CREATE TRIGGER ${name}`,
            `AFTER DELETE ON ${table.tableName}`,
            'BEGIN',
            `    INSERT INTO _pending_changes (table_name, row_id, operation, row_data) VALUES ('${table.tableName}', OLD.${table.rowIdColumn}, 'DELETE', NULL);`,
            'END',
        ].join('\n'),
    };
}

type PendingChangesTriggers = { sql: string; fingerprint: string };

function buildTriggers(tables: readonly TrackedTable[]): PendingChangesTriggers {
    const definitions = tables.flatMap((table) => [
        insertOrUpdateTrigger(table, 'INSERT'),
        insertOrUpdateTrigger(table, 'UPDATE'),
        deleteTrigger(table),
    ]);
    return {
        sql: definitions.map(({ name, sql }) => `DROP TRIGGER IF EXISTS ${name};\n${sql};`).join('\n'),
        /**
         * Story 361 — what INSTALLED_TRIGGERS_SQL reads back when these triggers are installed:
         * sqlite_master keeps each CREATE TRIGGER text verbatim. Comparing the two is a read, so an
         * open re-creates the triggers only when they are stale; rewriting them on every open took
         * the write lock while another build's worker could still hold the file, and boot hung.
         */
        fingerprint: [...definitions]
            .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
            .map(({ name, sql }) => `${name}:${sql}`)
            .join('\u0001'),
    };
}

// The offline fallback schema is this build's, so it takes every trigger.
export const PENDING_CHANGES_TRIGGERS_SQL = buildTriggers(TRACKED_TABLES).sql;

/**
 * Story 417 — the triggers a replica can carry: this build's tracked tables and columns, less
 * those its schema lacks. A replica older than this build (a device left alone across a
 * migration) failed to open on `CREATE TRIGGER … ON <missing table>`, and a trigger naming a
 * missing column fails every write to its table. The snapshot import brings both back.
 */
export function pendingChangesTriggersFor(replicaColumns: ReadonlyMap<string, ReadonlySet<string>>): PendingChangesTriggers {
    return buildTriggers(TRACKED_TABLES.flatMap((table) => {
        const present = replicaColumns.get(table.tableName);
        if (!present?.has(table.rowIdColumn)) return [];
        return [{ ...table, columns: table.columns.filter((column) => present.has(column)) }];
    }));
}

/** One `table.column` per line for every table in the replica — read by pendingChangesTriggersFor's caller. */
export const REPLICA_COLUMNS_SQL = `
    SELECT coalesce(group_concat(m.name || '.' || p.name, char(10)), '')
    FROM sqlite_master m, pragma_table_info(m.name) p
    WHERE m.type = 'table'`;

export const INSTALLED_TRIGGERS_SQL = `
    SELECT coalesce(group_concat(name || ':' || sql, char(1)), '')
    FROM (
        SELECT name, sql FROM sqlite_master
        WHERE type = 'trigger' AND name LIKE '\\_pending\\_changes\\_%' ESCAPE '\\'
        ORDER BY name
    )`;
