import sqlite3InitModule from '@sqlite.org/sqlite-wasm';
import { applyLocalDbArtifacts, prepareConnection } from './local-db-artifacts.js';
import { runWithReopenRetry, withExclusiveDbLock, type LocksApi } from './db-coordination.js';
import { shouldAdoptExisting } from './snapshot-adoption.js';
import { isBrokenReplicaError } from './probe-errors.js';
import { installConsoleCapture } from '../services/debug/client-log-buffer.js';
import { createComponentLogger } from '../utils/component-logger.js';

// Story 382: this realm's console reaches the shipped client log, like the window's.
installConsoleCapture({ realm: 'worker' });
const log = createComponentLogger('worker');

type WorkerRequest = {
    type: 'db-request';
    requestId: string;
    command: string;
    payload?: unknown;
};

type WorkerResponse = {
    requestId: string;
    ok: boolean;
    result?: unknown;
    error?: string;
};

type SQLite3Module = Awaited<ReturnType<typeof sqlite3InitModule>>;

type SqlExecOptions = {
    sql: string;
    bind?: unknown[];
    rowMode?: 'array' | 'object' | 'stmt' | number | string;
    resultRows?: unknown[];
    returnValue?: 'this' | 'resultRows' | 'saveSql';
};

type SqliteDb = {
    exec(sqlOrOptions: string | SqlExecOptions): unknown;
    changes(total?: boolean, sixtyFour?: boolean): number | bigint;
    selectValue(sql: string, bind?: unknown, asType?: number): unknown;
    close(): void;
};

type SqliteDbCtor = new (filename: string, mode?: string) => SqliteDb;

type SqliteModuleWithOo1 = SQLite3Module & {
    oo1: {
        DB: SqliteDbCtor;
        OpfsDb?: SqliteDbCtor & {
            importDb(filename: string, data: Uint8Array | ArrayBuffer): Promise<number>;
        };
    };
};

const DB_FILENAME = '/motivation.db';
/** DB_FILENAME as an entry of the OPFS root, where the OPFS VFS keeps it. */
const DB_ENTRY = 'motivation.db';
/** A read-only connection met a hot journal it is not allowed to roll back. */
const SQLITE_READONLY_ROLLBACK = 776;

let sqliteModulePromise: Promise<SqliteModuleWithOo1> | null = null;
let dbPromise: Promise<SqliteDb> | null = null;
let hasInitializedSchema = false;
let hasLoadedSnapshot = false;
let operationQueue: Promise<void> = Promise.resolve();

const isObject = (value: unknown): value is Record<string, unknown> => typeof value === 'object' && value !== null;

const SQLITE_MAGIC_HEADER = new TextEncoder().encode('SQLite format 3\0');

const hasValidSqliteHeader = (buffer: ArrayBuffer): boolean => {
    if (buffer.byteLength < SQLITE_MAGIC_HEADER.length) {
        return false;
    }

    const bytes = new Uint8Array(buffer, 0, SQLITE_MAGIC_HEADER.length);
    for (let i = 0; i < SQLITE_MAGIC_HEADER.length; i += 1) {
        if (bytes[i] !== SQLITE_MAGIC_HEADER[i]) {
            return false;
        }
    }
    return true;
};

const runSerialized = async <T>(operation: () => Promise<T>): Promise<T> => {
    const scheduled = operationQueue.then(operation, operation);
    operationQueue = scheduled.then(() => undefined, () => undefined);
    return scheduled;
};

// Web Locks is present in dedicated workers in Chrome; the helper degrades to
// in-worker serialization when absent (vitest, exotic contexts). Story 214.
const getLocks = (): LocksApi => (navigator as { locks?: LockManager }).locks;

const getSqliteModule = async (): Promise<SqliteModuleWithOo1> => {
    if (!sqliteModulePromise) {
        sqliteModulePromise = sqlite3InitModule().then((module) => module as SqliteModuleWithOo1);
    }
    return sqliteModulePromise;
};

const openDatabase = async (): Promise<SqliteDb> => {
    if (dbPromise) {
        try {
            return await dbPromise;
        } catch (err) {
            log.warn('Previous dbPromise was rejected, clearing and retrying...', err);
            dbPromise = null;
        }
    }

    dbPromise = (async () => {
        const sqlite3 = await getSqliteModule();
        log.debug('Opening database, OPFS available:', Boolean(sqlite3.oo1.OpfsDb));

        if (!sqlite3.oo1.OpfsDb) {
            log.warn('OPFS not available');
            throw new Error('OPFS not available');
        }

        try {
            const db = new sqlite3.oo1.OpfsDb(DB_FILENAME, 'c') as unknown as SqliteDb;
            prepareConnection(db);
            log.debug('OPFS database opened successfully');
            return db;
        } catch (err) {
            log.error('OPFS database open FAILED:', err);
            throw err;
        }
    })();

    return dbPromise;
};

/**
 * Drop the current connection so the next openDatabase() starts fresh. A
 * stale handle (file replaced by another window's import) may throw on
 * close() — that is exactly the situation this exists for, so the failure is
 * logged and swallowed. Story 214.
 */
const resetConnection = async (): Promise<void> => {
    const pending = dbPromise;
    dbPromise = null;
    if (!pending) {
        return;
    }
    try {
        (await pending).close();
    } catch (err) {
        log.warn('resetConnection — close failed (stale handle?), continuing:', err);
    }
};

const hasOpfsSnapshot = async (): Promise<boolean> => {
    const sqlite3 = await getSqliteModule();
    if (!sqlite3.oo1.OpfsDb) {
        const fallback = hasLoadedSnapshot || hasInitializedSchema;
        log.debug('hasOpfsSnapshot (no OPFS):', fallback, { hasLoadedSnapshot, hasInitializedSchema });
        return fallback;
    }

    // Story 360: asked of OPFS, not inferred from an open error — the OPFS VFS reports a missing
    // file as SQLITE_IOERR, the same code as a real I/O fault.
    if (!(await opfsFileExists(DB_ENTRY))) {
        log.debug('hasOpfsSnapshot: false (OPFS file not found)');
        return false;
    }

    const OpfsDb = sqlite3.oo1.OpfsDb;
    const hasLocalArtifacts = (mode: 'r' | 'w'): boolean => {
        const db = new OpfsDb(DB_FILENAME, mode);
        try {
            // File presence is NOT enough: every 'c'-mode open (any query racing
            // boot) auto-creates an empty file, and a wiped or interrupted
            // bootstrap leaves one behind — trusting it skips the snapshot
            // download and strands the app on "no such table" forever. Treat
            // the DB as existing only when the local artifacts are present,
            // the same condition every pending-changes consumer relies on.
            // Story 190.
            const artifactCount = db.selectValue(
                "SELECT count(*) FROM sqlite_master WHERE type = 'table' AND name = '_pending_changes'",
            );
            return Number(artifactCount) > 0;
        } finally {
            db.close();
        }
    };

    try {
        let hydrated: boolean;
        try {
            hydrated = hasLocalArtifacts('r');
        } catch (err) {
            if ((err as { resultCode?: unknown } | null)?.resultCode !== SQLITE_READONLY_ROLLBACK) throw err;
            // Story 359: a hot journal — the previous document was killed mid-write. Answering
            // "no DB" re-imported over the replica, queued changes and all, and the import then
            // played the journal onto the new file. A read-write open rolls it back like any
            // crash recovery.
            log.info('hasOpfsSnapshot — hot journal from an interrupted write; rolling it back');
            hydrated = hasLocalArtifacts('w');
        }
        log.debug(`hasOpfsSnapshot: ${hydrated} (file exists, local artifacts ${hydrated ? 'present' : 'missing'})`);
        return hydrated;
    } catch (err) {
        // Story 360: the file is there, so a failed read is never "no database". A broken file is
        // said out loud and replaced; anything else is thrown for the bootstrap to report.
        if (!isBrokenReplicaError(err)) throw err;
        log.error(
            'hasOpfsSnapshot: the replica is unreadable, so the snapshot import will replace it. Its queued changes, verbatim:',
            readQueuedChangesVerbatim(OpfsDb),
            err,
        );
        return false;
    }
};

const opfsFileExists = async (name: string): Promise<boolean> => {
    try {
        await (await navigator.storage.getDirectory()).getFileHandle(name);
        return true;
    } catch (err) {
        if (err instanceof DOMException && err.name === 'NotFoundError') return false;
        throw err;
    }
};

/** Best effort, for the record before an import replaces a broken replica (story 215's rule). */
const readQueuedChangesVerbatim = (OpfsDb: SqliteDbCtor): unknown => {
    try {
        const db = new OpfsDb(DB_FILENAME, 'r');
        try {
            return db.exec({ sql: 'SELECT * FROM _pending_changes ORDER BY id', rowMode: 'object', returnValue: 'resultRows' });
        } finally {
            db.close();
        }
    } catch (err) {
        return `(unreadable as well: ${err instanceof Error ? err.message : String(err)})`;
    }
};

/**
 * The on-disk DB's `sync.snapshot_generation`, or 0 when absent/unreadable.
 * Generation > 0 means a real server snapshot baseline — an empty-schema
 * fallback has no generation row (a production server is never at generation
 * 0; the e2e seed bumps it, story 215). Story 214's import-once adoption
 * compares this against the incoming snapshot's expected generation.
 */
const currentSnapshotGeneration = async (): Promise<number> => {
    const sqlite3 = await getSqliteModule();
    if (!sqlite3.oo1.OpfsDb) {
        return hasLoadedSnapshot ? 1 : 0;
    }
    try {
        const readOnlyDb = new sqlite3.oo1.OpfsDb(DB_FILENAME, 'r');
        try {
            const value = readOnlyDb.selectValue(
                "SELECT value FROM settings WHERE key = 'sync.snapshot_generation'",
            );
            const generation = Number(value ?? 0);
            return Number.isFinite(generation) && generation > 0 ? generation : 0;
        } finally {
            readOnlyDb.close();
        }
    } catch {
        return 0;
    }
};

const ensureSchema = async (): Promise<void> => {
    await withExclusiveDbLock(getLocks(), () => runSerialized(async () => {
        log.debug('ensureSchema — applying local DB artifacts...');
        const db = await openDatabase();
        applyLocalDbArtifacts(db);
        hasInitializedSchema = true;
        log.debug('ensureSchema — DONE');
    }));
};

const executeQuery = async (payload: unknown): Promise<unknown[]> => {
    if (!isObject(payload) || typeof payload.sql !== 'string') {
        throw new Error('query payload must include sql string');
    }
    const requestPayload = payload as { sql: string; params?: unknown[] };

    return runSerialized(() => runWithReopenRetry({ open: openDatabase, reset: resetConnection }, (db) => {
        const resultRows: unknown[] = [];

        const options: SqlExecOptions = {
            sql: requestPayload.sql,
            rowMode: 'object',
            resultRows,
            returnValue: 'resultRows',
        };

        if (Array.isArray(requestPayload.params) && requestPayload.params.length > 0) {
            options.bind = requestPayload.params;
        }

        db.exec(options);
        return resultRows;
    }));
};

const executeStatement = async (payload: unknown): Promise<{ changes: number; lastInsertRowid: number }> => {
    if (!isObject(payload) || typeof payload.sql !== 'string') {
        throw new Error('execute payload must include sql string');
    }
    const requestPayload = payload as { sql: string; params?: unknown[] };

    return runSerialized(() => runWithReopenRetry({ open: openDatabase, reset: resetConnection }, (db) => {
        const options: SqlExecOptions = {
            sql: requestPayload.sql,
            returnValue: 'this',
        };

        if (Array.isArray(requestPayload.params) && requestPayload.params.length > 0) {
            options.bind = requestPayload.params;
        }

        db.exec(options);

        const changesValue = db.changes();
        const lastInsertRowidValue = db.selectValue('SELECT last_insert_rowid()');

        return {
            changes: Number(changesValue ?? 0),
            lastInsertRowid: Number(lastInsertRowidValue ?? 0),
        };
    }));
};

/**
 * Story 359 — what a refresh learns: the snapshot went in (imported or adopted), or it was
 * refused because the replica holds queued changes it would have discarded.
 */
type LoadSnapshotResult = { applied: true } | { applied: false; pendingCount: number };

const countPendingChanges = async (): Promise<number> => {
    const db = await openDatabase();
    const hasQueue = Number(db.selectValue("SELECT count(*) FROM sqlite_master WHERE type = 'table' AND name = '_pending_changes'")) > 0;
    return hasQueue ? Number(db.selectValue('SELECT count(*) FROM _pending_changes')) : 0;
};

const loadSnapshot = async (payload: unknown): Promise<LoadSnapshotResult> => {
    if (!isObject(payload) || !(payload.buffer instanceof ArrayBuffer)) {
        throw new Error('load-snapshot payload must include buffer ArrayBuffer');
    }
    const snapshotBuffer = payload.buffer;
    // The generation the caller expects this import to bring the DB to (from
    // /snapshot/info). null when unknown — legacy adopt-on-any-baseline then
    // applies (correct for the story-214 dual-window bootstrap race only).
    const expectedGeneration = typeof payload.expectedGeneration === 'number' && Number.isFinite(payload.expectedGeneration)
        ? payload.expectedGeneration
        : null;
    const requireNoPending = payload.requireNoPending === true;
    const replace = payload.replace === true;
    log.debug('loadSnapshot — buffer size:', snapshotBuffer.byteLength, 'expectedGeneration:', expectedGeneration);

    const sqlite3 = await getSqliteModule();
    if (!sqlite3.oo1.OpfsDb) {
        throw new Error('OPFS is unavailable in this environment; cannot import SQLite snapshot');
    }

    if (!hasValidSqliteHeader(snapshotBuffer)) {
        log.error('loadSnapshot — INVALID SQLite header!');
        throw new Error('Invalid SQLite snapshot header');
    }
    log.debug('loadSnapshot — valid SQLite header confirmed');

    return withExclusiveDbLock(getLocks(), () => runSerialized(async (): Promise<LoadSnapshotResult> => {
        // Story 359 (pwa-offline-12): the "nothing queued" check runs in the same locked slot as
        // the import. Checked on the main thread before the request, a write that landed in the
        // gap was captured by its trigger and then wiped by the import.
        if (requireNoPending) {
            const pendingCount = await countPendingChanges();
            if (pendingCount > 0) {
                log.info(`loadSnapshot — refused: ${pendingCount} queued change(s) would be discarded`);
                return { applied: false, pendingCount };
            }
        }

        // Import-once (story 214): while this window waited for the lock,
        // another window may have completed the same import. Replacing the
        // file AGAIN would invalidate that window's open handles — the exact
        // mechanism that produced the 08:07Z SQLITE_IOERR storm. Adopt the
        // existing DB instead: drop any stale handle and reopen fresh.
        // Unless the caller asked to throw this file away (story 360's "Discard N and pull").
        const onDiskGeneration = await currentSnapshotGeneration();
        if (!replace && shouldAdoptExisting(onDiskGeneration, expectedGeneration)) {
            log.info(`loadSnapshot — on-disk generation ${onDiskGeneration} already satisfies expected ${expectedGeneration ?? '(unknown)'} (another window imported); adopting instead of re-importing`);
            await resetConnection();
            await openDatabase();
            hasLoadedSnapshot = true;
            hasInitializedSchema = true;
            return { applied: true };
        }

        try {
            await resetConnection();
            log.debug('loadSnapshot — old DB closed, importing...');

            await sqlite3.oo1.OpfsDb!.importDb(DB_FILENAME, snapshotBuffer);
            log.debug('loadSnapshot — importDb done, re-opening...');
            const importedDb = new sqlite3.oo1.OpfsDb!(DB_FILENAME, 'c') as unknown as SqliteDb;
            prepareConnection(importedDb);
            hasLoadedSnapshot = true;
            hasInitializedSchema = true;
            dbPromise = Promise.resolve(importedDb);
            log.debug('loadSnapshot — snapshot loaded and triggers applied');
            return { applied: true };
        } catch (err) {
            log.error('loadSnapshot — FAILED:', err);
            // Leave dbPromise unset so the next openDatabase call can retry.
            dbPromise = null;
            throw err;
        }
    }));
};

const postResponse = (port: MessagePort, response: WorkerResponse): void => {
    port.postMessage(response);
};

const wipeOpfs = async (): Promise<void> => {
    await withExclusiveDbLock(getLocks(), async () => {
        log.debug('wipeOpfs — closing DB...');
        await resetConnection();
        try {
            await (await navigator.storage.getDirectory()).removeEntry(DB_ENTRY);
        } catch (err) {
            if (err instanceof DOMException && err.name === 'NotFoundError') {
                log.debug('wipeOpfs — no OPFS file to remove');
                return;
            }
            // Story 382 (consistency-01): a file another window still holds is not wiped, and a
            // reload would boot the same DB. Thrown, so the caller and handleRequest's log say so.
            throw err;
        }
        log.debug('wipeOpfs — OPFS file removed');
    });
};

const handleRequest = async (request: WorkerRequest): Promise<unknown> => {
    log.debug('handleRequest:', request.command);
    const start = performance.now();
    try {
        let result: unknown;
        switch (request.command) {
            case 'db-exists':
                result = await hasOpfsSnapshot();
                break;
            case 'load-snapshot':
                result = await loadSnapshot(request.payload);
                break;
            case 'schema-init':
                await ensureSchema();
                result = undefined;
                break;
            case 'query':
                result = await executeQuery(request.payload);
                break;
            case 'execute':
                result = await executeStatement(request.payload);
                break;
            case 'release-connection':
                // Story 266: the owning document is going away (pagehide), so
                // free the OPFS sync-access handle NOW instead of leaving the
                // incoming document's db-exists blocked behind it. Deliberately
                // NOT serialized behind `operationQueue`: a queue that is stuck
                // is exactly the situation this exists for, and any in-flight
                // result belongs to a document that is being torn down anyway.
                // A bfcache restore reopens lazily via openDatabase(), and
                // runWithReopenRetry (story 214) already covers a handle that
                // went away under an operation.
                await resetConnection();
                result = undefined;
                break;
            case 'wipe':
                await wipeOpfs();
                result = undefined;
                break;
            default:
                throw new Error(`Unknown DB worker command: ${request.command}`);
        }
        const elapsed = (performance.now() - start).toFixed(1);
        log.info(`handleRequest ${request.command} — OK (${elapsed}ms)`);
        return result;
    } catch (err) {
        const elapsed = (performance.now() - start).toFixed(1);
        log.error(`handleRequest ${request.command} — FAILED (${elapsed}ms):`, err);
        throw err;
    }
};

const workerScope = globalThis as unknown as {
    onmessage: ((event: MessageEvent<WorkerRequest>) => void) | null;
};

workerScope.onmessage = async (event: MessageEvent<WorkerRequest>) => {
    const request = event.data;
    const responsePort = event.ports?.[0];

    if (!request || request.type !== 'db-request' || !responsePort) {
        log.warn('Ignoring malformed DB worker message', {
            hasRequest: Boolean(request),
            requestType: request?.type,
            hasResponsePort: Boolean(responsePort),
        });
        return;
    }

    try {
        const result = await handleRequest(request);
        postResponse(responsePort, {
            requestId: request.requestId,
            ok: true,
            result,
        });
    } catch (error) {
        postResponse(responsePort, {
            requestId: request.requestId,
            ok: false,
            error: error instanceof Error ? error.message : 'Unknown worker error',
        });
    }
};
