import { PENDING_CHANGES_TABLE_SQL } from '@motivation/shared';
import { OFFLINE_FALLBACK_SCHEMA_SQL } from './fallback-schema.js';
import {
    INSTALLED_TRIGGERS_SQL,
    PENDING_CHANGES_TRIGGERS_SQL,
    REPLICA_COLUMNS_SQL,
    pendingChangesTriggersFor,
} from './pending-changes.js';

type SqlExecTarget = {
    exec(sql: string): unknown;
};

// Full init — used when there is no snapshot (pure offline from scratch).
// Creates all user-data tables, the _pending_changes table, and triggers.
export function applyLocalDbArtifacts(db: SqlExecTarget): void {
    db.exec(OFFLINE_FALLBACK_SCHEMA_SQL);
    db.exec(PENDING_CHANGES_TABLE_SQL);
    db.exec(PENDING_CHANGES_TRIGGERS_SQL);
}

type ConnectionTarget = SqlExecTarget & {
    selectValue(sql: string): unknown;
};

function readReplicaColumns(db: ConnectionTarget): Map<string, Set<string>> {
    const columns = new Map<string, Set<string>>();
    for (const line of String(db.selectValue(REPLICA_COLUMNS_SQL)).split('\n')) {
        const [table, column] = line.split('.');
        if (!column) continue;
        columns.set(table, (columns.get(table) ?? new Set<string>()).add(column));
    }
    return columns;
}

/**
 * Story 361 — run on every read-write connection the worker opens. Foreign keys are a
 * per-connection setting and sqlite-wasm defaults them OFF (the server's node:sqlite has them
 * ON), so offline deletes skipped every CASCADE / SET NULL / RESTRICT. A replica's triggers are
 * re-created when they are not this build's: refreshing them only on import left a new build
 * running the previous build's. The check is a read — see buildTriggers' fingerprint. A replica
 * older than this build gets the triggers its schema can carry (story 417). An empty file has no
 * tables to hang triggers on yet.
 */
export function prepareConnection(db: ConnectionTarget): void {
    db.exec('PRAGMA foreign_keys = ON;');
    const isReplica = Number(db.selectValue("SELECT count(*) FROM sqlite_master WHERE type = 'table' AND name = '_pending_changes'")) > 0;
    if (!isReplica) return;
    const triggers = pendingChangesTriggersFor(readReplicaColumns(db));
    if (db.selectValue(INSTALLED_TRIGGERS_SQL) !== triggers.fingerprint) {
        db.exec(triggers.sql);
    }
}