const SQLITE_CORRUPT = 11;
const SQLITE_NOTADB = 26;

/**
 * Whether a failed read of a replica that exists says the file itself is broken (story 360,
 * pwa-offline-14). Only an import heals that, after its queued changes are recorded and the
 * failure said out loud. Anything else — contention included — is no verdict on the file:
 * re-importing over a replica that was only momentarily unreadable is what corrupted it
 * (story 281).
 */
export function isBrokenReplicaError(err: unknown): boolean {
    const resultCode = (err as { resultCode?: unknown } | null)?.resultCode;
    if (typeof resultCode !== 'number') return false;
    const primary = resultCode & 0xff;
    return primary === SQLITE_CORRUPT || primary === SQLITE_NOTADB;
}
